  if(!Number.isFinite(row.value)){drawing=false;continue;}
  const x=left+(right-left)*row.distance/profile.length,y=bottom-(row.value-min)/(max-min)*(bottom-top);
  if(drawing)ctx.lineTo(x,y);else ctx.moveTo(x,y);
  drawing=true;
