   const name=String(dataset.name||'volume').normalize('NFKD')
    .replace(/[^a-zA-Z0-9_-]+/g,'_').replace(/^_+|_+$/g,'').slice(0,48)||'volume';
   const content=format==='cube'?volumeCubeText(dataset.grid):volumeXsfText(dataset.grid);
