 for(const mesh of atomMesh){
  const tier=atomLodTier(atomData.length,(mesh.userData.maxAtomRadius||1)*pixels/worldHeight,renderQuality);
  mesh.geometry=geometries[tier];mesh.userData.atomLodTier=tier;
 }
