  if(h<0||h===0&&k<0||h===0&&k===0&&l<0)continue;
  const invD=new THREE.Vector3().addScaledVector(reciprocal[0],h)
   .addScaledVector(reciprocal[1],k).addScaledVector(reciprocal[2],l).length();
  if(invD>maxInverseD)continue;
