 const warnings=scattering==='neutron'&&strongAbsorbers.length?
  ['Uyarı: '+strongAbsorbers.join(', ')+' için koherent b sanal bileşeni ve nötron absorpsiyonu modellenmiyor; göreli şiddetlere dikkat.']:[];
