 $('presetCell').textContent=[example.cell.a,example.cell.b,example.cell.c].map(value=>value.toFixed(3)).join(' × ')+' Å';
 $('presetElements').textContent=example.elements.join(', ');
 $('presetSpacegroup').textContent=example.spacegroup;
 $('presetAngles').textContent=[example.cell.alpha,example.cell.beta,example.cell.gamma].map(value=>Number(value).toFixed(1)+'°').join(' · ');
 $('presetVolume').textContent=example.volume.toLocaleString('tr-TR',{maximumFractionDigits:2})+' Å³';
