const LAST_CRYSTAL_KEY='kristalyapi.last-structure.v2';

/* In-memory bounded snapshots; storage persists only the latest crystal.
   Undo/redo operates on complete scientific structure state, not camera/UI focus. */
function createEditorHistory(limit=60,maxSnapshot=380000){
 if(!Number.isInteger(limit)||limit<1||!Number.isInteger(maxSnapshot)||maxSnapshot<100)throw Error('Geçersiz geçmiş sınırı.');
 const past=[],future=[];
 let present=null;
 return {
  record(snapshot){
   if(typeof snapshot!=='string'||snapshot.length>maxSnapshot||!snapshot){
    past.length=0;future.length=0;present=null;return false;
   }
   if(present===snapshot)return false;
   if(present!==null){
    past.push(present);
    if(past.length>limit)past.splice(0,past.length-limit);
   }
   present=snapshot;future.length=0;
   return true;
  },
  canUndo:()=>past.length>0,
  canRedo:()=>future.length>0,
  undo(){
   if(!past.length)return null;
   future.push(present);present=past.pop();return present;
  },
  redo(){
   if(!future.length)return null;
   past.push(present);present=future.pop();return present;
  },
  current:()=>present,
  counts:()=>({undo:past.length,redo:future.length}),
 };
}
let editorHistory=createEditorHistory();
let historyApplying=false;
function updateHistoryButtons(){
 $('undoBtn').disabled=!editorHistory.canUndo();
 $('redoBtn').disabled=!editorHistory.canRedo();
}
function recordHistoryChange(){
 if(historyApplying||workspaceSwitching)return;
 editorHistory.record(JSON.stringify(lastCrystalPayload(state)));
 updateHistoryButtons();
}
function restoreHistorySnapshot(serialized){
 const restored=loadProject(serialized);
 const cellChanged=JSON.stringify(state.cell)!==JSON.stringify(restored.cell);
 const supercellChanged=JSON.stringify(state.rep)!==JSON.stringify(restored.rep);
 const structureChanged=state.name!==restored.name||cellChanged;
 state={...state,...restored};
 // A density/potential dataset is not part of the crystal history. Do not
 // leave a previously imported volumetric dataset over an unrelated crystal.
 if(structureChanged&&densityGrid)resetVolume();
 selected=[]; // Atom indices may no longer exist after undo/redo.
 syncControls();
 if(build()===false)throw Error('Kristal geçmişindeki yapı çizilemedi.');
 if(cellChanged||supercellChanged)fit();
}
function applyHistory(direction){
 const action=direction==='undo'?editorHistory.undo:direction==='redo'?editorHistory.redo:null;
 if(!action||!editorHistory[direction==='undo'?'canUndo':'canRedo']())return false;
 const before=editorHistory.current(),previousState=state;
 const snapshot=action();
 historyApplying=true;
 try{
  restoreHistorySnapshot(snapshot);
  updateHistoryButtons();
  return true;
 }catch(err){
  // Restore the history pointer and model if a damaged snapshot cannot render.
  if(direction==='undo')editorHistory.redo();else editorHistory.undo();
  state=previousState;
  try{syncControls();build();}catch(e){console.error('Geçmiş geri yükleme kurtarılamadı:',e);}
  updateHistoryButtons();
  inform('Geri alma / yineleme başarısız: '+err.message);
  return false;
 }finally{historyApplying=false;}
}
function isEditableHistoryTarget(target){
 if(!target||typeof target.closest!=='function')return false;
 return !!target.closest('input,textarea,[contenteditable="true"],[role="textbox"]');
}
function historyShortcut(event){
 if(!(event.ctrlKey||event.metaKey)||event.altKey||isEditableHistoryTarget(event.target))return false;
 const key=String(event.key||'').toLowerCase();
 const command=key==='z'?(event.shiftKey?'redo':'undo'):key==='y'&&!event.shiftKey?'redo':null;
 if(!command)return false;
 event.preventDefault();
 applyHistory(command);
 return true;
}

