   bonds:obj.bonds!==false,cellVisible:obj.cellVisible!==false,boundary:obj.boundary!==false,
   labels:!!obj.labels,axes:!!obj.axes,autoRotate:!!obj.autoRotate,
   poly:parsed.poly,polyCenters:parsed.polyCenters,
