/* Read-only bridge for the reciprocal-space page: the active workspace's
   structure (symmetry-expanded P1 list) and the editor's validated physics. */
function reciprocalHost(){
 return {
  structure(){
   const sites=state.symmetryEnabled?expandSites(state.sites,state.sgSetting,1000):
    state.sites.map((site,i)=>({...site,sourceSiteIndex:i}));
   const sg=state.symmetryEnabled?String(SPACE_NAMES[state.sgNumber]||state.sgSetting).split('=')[0].trim():'P1';
   return {name:state.name,workspace:activeWorkspace()?.label||'',symmetry:sg,cell:{...validateCell(state.cell)},
    sites:sites.map(site=>({...site,symbol:cleanSymbol(site.symbol),x:Number(site.x),y:Number(site.y),z:Number(site.z)}))};
  },
  structureFactor,scatteringFactor,powderPattern,powderProfile,elementColor,
  atomicNumber:symbol=>PERIODIC_SYMBOLS.indexOf(cleanSymbol(symbol))+1,
  isotropicU(site,cell){
   if(Number.isFinite(site.uIso)&&site.uIso>0)return site.uIso;
   if(site.adp){const U=adpToCartesian(site.adp,cell);return Math.max(0,(U[0][0]+U[1][1]+U[2][2])/3);}
   return 0;
  }
 };
}
function codSetLoading(busy){
 codBusy=busy;
 $('codSubmit').disabled=busy;
 $('codSubmit').textContent=busy?'Aranıyor…':'⌕ COD’da ara';
}
async function runCodSearch(){
 if(codBusy)return;
 let params,url;
 try{params=codSearchParamsFromForm();url=codSearchUrl(params);}
 catch(e){codSearchMessage(e.message,true);return;}
 $('codExternalSearch').href=url;$('codExternalSearch').hidden=false;
 codResults=[];codPage=0;renderCodResults();
 codSetLoading(true);codSearchMessage('COD veritabanında aranıyor. Sonuçlar yüklenene kadar bekleyin…',false,true);
 const requestId=++codGeneration,controller=new AbortController();codAbort=controller;
 try{
  const urls=codSearchUrls(params,$('codConnection').value),failures=[];
  let all=null,used='';
  for(const endpoint of urls){
   try{
    const body=await fetchCodText(endpoint,{mode:$('codConnection').value,signal:controller.signal,limit:6500000});
    const payload=JSON.parse(body);
    if(payload?.errors?.length)throw Error(payload.errors[0]?.detail||'API sorgusu reddedildi.');
    all=normalizeCodResults(payload);
    used=endpoint.includes('/optimade/')?'OPTIMADE':'COD klasik';
    break;
   }catch(error){
    if(controller.signal.aborted)throw error;
    failures.push(error.message);
   }
  }
  if(!all)throw Error(failures.join(' / '));
  if(requestId!==codGeneration)return;
  codResults=all.slice(0,COD_MAX_VISIBLE);codPage=0;
  renderCodResults();
  const suffix=all.length>COD_MAX_VISIBLE?' İlk '+COD_MAX_VISIBLE+' sonuç gösterildi; daha dar filtre önerilir.':'';
  codSearchMessage(all.length?used+' üzerinden '+all.length.toLocaleString('tr-TR')+' kayıt alındı.'+suffix:'Bu ölçütlerle COD kaydı bulunamadı.');
 }catch(e){
  if(requestId!==codGeneration)return;
  codSearchMessage('Arama tamamlanamadı: '+e.message+'. İstersen aramayı COD sitesinde açıp CIF dosyasını elle yükleyebilirsin.',true);
 }finally{
  if(requestId===codGeneration){codAbort=null;codSetLoading(false);}
 }
}
/* No public CORS proxy: the browser cannot read a download from a server
   without CORS. Cache previous successful imports; provide a real file picker
   if neither official COD endpoint permits cross-origin fetch. */
function codCacheKey(id){
 codCifUrl(id);
 const url=new URL(window.location.href);url.hash='';url.search='?cod-cif-cache='+id;
 return url.href;
}
async function codCachedCif(id){
 if(!('caches' in window))return null;
 try{const cache=await window.caches.open(COD_CACHE_NAME);
  const response=await cache.match(codCacheKey(id));
  if(!response)return null;
  const content=await response.text();
  return content.length<=4000000&&/^\s*(?:data_|#)/i.test(content)?content:null;
 }catch(e){return null;}
}
async function codRememberCif(id,content){
 if(!('caches' in window)||content.length>4000000)return;
 try{
  const cache=await window.caches.open(COD_CACHE_NAME);
  await cache.put(codCacheKey(id),new Response(content,{headers:{'Content-Type':'chemical/x-cif'}}));
  const keys=await cache.keys();
  if(keys.length>40)await Promise.all(keys.slice(0,keys.length-40).map(key=>cache.delete(key)));
 }catch(e){console.warn('COD çevrimdışı önbelleğe alınamadı:',e);}
}
function codOptimadeToCif(payload,id){
 const entry=Array.isArray(payload?.data)?payload.data.find(x=>String(x.id)===String(id)):payload?.data;
 if(!entry||String(entry.id)!==String(id))throw Error('OPTIMADE yanıtında istenen COD kaydı bulunamadı.');
 const a=entry.attributes||{},vectors=a.lattice_vectors,coords=a.cartesian_site_positions,names=a.species_at_sites;
 if(!Array.isArray(vectors)||vectors.length!==3||vectors.some(v=>!Array.isArray(v)||v.length!==3||v.some(x=>!Number.isFinite(x))))
  throw Error('OPTIMADE yanıtında tam örgü vektörleri bulunmuyor.');
 if(!Array.isArray(coords)||!Array.isArray(names)||coords.length!==names.length||!coords.length||coords.length>1000)
  throw Error('OPTIMADE yanıtında atom koordinatları eksik veya sınırın üzerinde.');
 const B=vectors.map(v=>new THREE.Vector3(...v)),cell=validateCell(metric(B));
 const species=new Map((a.species||[]).map(x=>[x.name,x]));
 let count=0;
 const lines=['data_COD_'+id,"_symmetry_space_group_name_H-M 'P 1'",'_symmetry_Int_Tables_number 1',
  ...['a','b','c'].map(k=>'_cell_length_'+k+' '+cell[k].toFixed(8)),
  ...['alpha','beta','gamma'].map(k=>'_cell_angle_'+k+' '+cell[k].toFixed(8)),
  'loop_','_atom_site_label','_atom_site_type_symbol','_atom_site_fract_x','_atom_site_fract_y','_atom_site_fract_z','_atom_site_occupancy'];
 coords.forEach((position,i)=>{
  if(!Array.isArray(position)||position.length!==3||position.some(x=>!Number.isFinite(x)))throw Error('Geçersiz OPTIMADE atom koordinatı.');
  const f=toFrac(new THREE.Vector3(...position),B);
  const sp=species.get(names[i]);
  if(!sp||!Array.isArray(sp.chemical_symbols)||!Array.isArray(sp.concentration))throw Error('OPTIMADE tür bilgisi eksik.');
  sp.chemical_symbols.forEach((symbol,j)=>{
   if(symbol==='vacancy'||symbol==='X')return;
   const element=codCleanSymbol(symbol),occupancy=Number(sp.concentration[j]);
   if(!Number.isFinite(occupancy)||occupancy<0||occupancy>1)throw Error('Geçersiz OPTIMADE doluluk oranı.');
   if(occupancy===0)return;
   count++;
   if(count>1000)throw Error('Çok sayıda atom: OPTIMADE üst sınırı 1000.');
   lines.push(element+count+' '+element+' '+f.map(n=>frac(n).toFixed(9)).join(' ')+' '+occupancy.toFixed(6));
  });
 });
 if(!count)throw Error('OPTIMADE kaydı kullanılabilir atom içermiyor.');
 return lines.join('\n')+'\n';
}
async function codOpenCif(record,cif,originalName){
 if(!/^\s*(?:data_|#)/i.test(cif))throw Error('Dosya CIF biçiminde değil.');
 const file=new File([cif],record.codId+'.cif',{type:'chemical/x-cif'});
 await importFile(file);
 state.name=(record.formula||'COD '+record.codId)+' · COD '+record.codId;
 state.detail=(state.detail||'')+' · COD '+record.codId;
 state.cifOriginal=originalCifRecord(state,cif);
 build();
 await codRememberCif(record.codId,cif);
 $('codImportHelp').hidden=true;
 window.location.hash='kristal';
 syncLibraryNavigation();
 inform('COD '+record.codId+' aktarıldı'+(originalName?' · '+originalName:'')+'.');
}
async function importCodEntry(record){
 const workspaceId=activeWorkspaceId;
 const verifyWorkspace=()=>{if(workspaceId!==activeWorkspaceId)throw Error('COD kaydı yüklenirken çalışma alanı değişti; lütfen yeniden deneyin.');};
 const id=String(record.codId),cached=await codCachedCif(id);
 if(cached){
  try{verifyWorkspace();await codOpenCif(record,cached,'çevrimdışı önbellek');return;}catch(e){verifyWorkspace();console.warn('Önbellek CIF geçersiz:',e);}
 }
 const mode=$('codConnection').value,failures=[];
 // Prefer the authoritative CIF when our own Worker is available: this
 // preserves original symmetry, bibliographic fields and asymmetric sites.
 const workerCif=mode==='worker'||(mode==='auto'&&!!codWorkerBase);
 if(workerCif){
  try{
   const cif=await fetchCodText(codCifUrl(id),{mode:'worker',limit:4000000});
   verifyWorkspace();
   await codOpenCif(record,cif,'Cloudflare Worker · COD CIF');
   return;
  }catch(e){failures.push('Worker CIF: '+e.message);}
 }
 if(mode!=='direct'){
  try{
   const content=await fetchCodText(codOptimadeItemUrl(id),{mode,limit:4000000});
   verifyWorkspace();
   const cif=codOptimadeToCif(JSON.parse(content),id);
   await codOpenCif(record,cif,'OPTIMADE');
   return;
  }catch(e){failures.push('OPTIMADE: '+e.message);}
 }
 if(mode!=='optimade'&&!workerCif){
  try{
   const cif=await fetchCodText(codCifUrl(id),{mode,limit:4000000});
   verifyWorkspace();
   await codOpenCif(record,cif,'COD CIF');
   return;
  }catch(e){failures.push('COD CIF: '+e.message);}
 }
 throw Error(failures.join(' / '));
}
