const QUICKBAR_MILLER_FIELDS=[['quickH','h'],['quickK','k'],['quickL','l'],['quickSlabThickness','slabThickness']];
function syncAnalysisAvailability(){
 const hasThermalData=state.sites.some(site=>!!site.adp||Number.isFinite(site.uIso));
 $('adpLevel').disabled=!state.adpVisible||!hasThermalData;
 $('adpLevel').title=!hasThermalData?'Bu yapıda Uij/Uiso termal veri yok.':
  !state.adpVisible?'Önce termal elipsoitler ikonunu açın.':'Elipsoit olasılık düzeyi';
 for(const id of ['polyCut','polyNeighbors','polyColor','polyOpacity'])$(id).disabled=!state.polyCenters?.length;
}
function syncQuickbar(){
 $('quickStyle').value=$('style').value;
 for(const button of document.querySelectorAll('[data-quick-flag]'))
  button.setAttribute('aria-pressed',String($(button.dataset.quickFlag).checked));
 for(const [quick,source,output] of [['quickAtomScale','atomScale','quickAtomScaleVal'],['quickBondCut','bondCut','quickBondCutVal']]){
  $(quick).value=$(source).value;$(output).value=Number($(source).value).toFixed(2);
 }
 for(const [quick,source] of QUICKBAR_MILLER_FIELDS)$(quick).value=$(source).value;
 $('quickShowPlane').setAttribute('aria-pressed',String($('showPlane').checked));
 $('quickRepeatMillerPlanes').setAttribute('aria-pressed',String($('repeatMillerPlanes').checked));
 syncAnalysisAvailability();
}
function applyQuickMiller(){
 const hkl=['quickH','quickK','quickL'].map(id=>Number($(id).value));
 const thickness=Number($('quickSlabThickness').value);
 if(hkl.some((v,i)=>!$(['quickH','quickK','quickL'][i]).value.trim()||!Number.isInteger(v)||Math.abs(v)>8)
  ||!$('quickSlabThickness').value.trim()||!Number.isFinite(thickness)||thickness<.1||thickness>100){
  inform('Miller indisleri -8…8 arasında tam sayı, kesit kalınlığı 0,1–100 Å olmalıdır.');return;
 }
 const previousPlane={...state.plane};
 const originals=QUICKBAR_MILLER_FIELDS.map(([,id])=>[id,$(id).value]);
 const checkboxes=[['showPlane',$('showPlane').checked],['repeatMillerPlanes',$('repeatMillerPlanes').checked]];
 for(const [quick,source] of QUICKBAR_MILLER_FIELDS)$(source).value=$(quick).value;
 $('showPlane').checked=$('quickShowPlane').getAttribute('aria-pressed')==='true';
 $('repeatMillerPlanes').checked=$('quickRepeatMillerPlanes').getAttribute('aria-pressed')==='true';
 try{previewPlane();build();}
 catch(error){
  state.plane=previousPlane;
  for(const [id,value] of originals)$(id).value=value;
  for(const [id,checked] of checkboxes)$(id).checked=checked;
  syncQuickbar();inform('Miller düzlemleri: '+error.message);
 }
}
function initQuickbar(){
 $('quickStyle').onchange=event=>{$('style').value=event.target.value;$('style').dispatchEvent(new Event('change',{bubbles:true}));syncQuickbar();};
 for(const button of document.querySelectorAll('[data-quick-flag]')){
  button.onclick=()=>{const source=$(button.dataset.quickFlag);source.checked=!source.checked;source.dispatchEvent(new Event('change',{bubbles:true}));syncQuickbar();};
  $(button.dataset.quickFlag).addEventListener('change',syncQuickbar);
 }
 $('style').addEventListener('change',syncQuickbar);
 for(const [quick,source] of [['quickAtomScale','atomScale'],['quickBondCut','bondCut']]){
  $(quick).addEventListener('input',event=>{$(source).value=event.target.value;$(source).dispatchEvent(new Event('input',{bubbles:true}));syncQuickbar();});
  $(quick).addEventListener('change',()=>$(source).dispatchEvent(new Event('change',{bubbles:true})));
  $(source).addEventListener('input',syncQuickbar);
  $(source).addEventListener('change',syncQuickbar);
 }
 for(const [quick,source] of QUICKBAR_MILLER_FIELDS){$(quick).addEventListener('change',applyQuickMiller);$(source).addEventListener('change',syncQuickbar);}
 for(const [quick,source] of [['quickShowPlane','showPlane'],['quickRepeatMillerPlanes','repeatMillerPlanes']]){
  $(quick).onclick=()=>{$(quick).setAttribute('aria-pressed',String($(quick).getAttribute('aria-pressed')!=='true'));applyQuickMiller();};
  $(source).addEventListener('change',syncQuickbar);
 }
 syncQuickbar();
}

