try{
 const host=reciprocalHost();
 powderLesson=initPowderLesson(host);
 semiconductorLesson=initSemiconductorLesson(host);
 syncLibraryNavigation();
}catch(err){console.error('Eğitim sayfaları başlatılamadı:',err);}
